import type { RequestHandler } from './$types';
import { cacheFor, getApiFile } from '$lib/server/apiFiles';
import { sitemapMaxAge } from '$lib/server/sitemapCache';

/**
 * `/sitemaps/{file}.xml`: relays the sitemaps generated by the Butterfly API
 * (sitemap plugin, configured in the back-office; its `publicBase` is
 * `{PUBLIC_BASE_URL}/sitemaps`). Status (404 included) and body pass through.
 */
export const GET: RequestHandler = async ({ fetch, params }) => {
  if (!/^[a-z0-9]+(-[a-z0-9]+)*\.xml$/.test(params.file)) {
    return new Response('Not found', { status: 404, headers: { 'Cache-Control': 'no-store' } });
  }

  const file = await getApiFile(fetch, `/v1/sitemaps/${params.file}`);
  const ok = file.status === 200;

  return new Response(file.body, {
    status: file.status,
    headers: {
      'Content-Type': ok ? 'application/xml; charset=utf-8' : file.contentType || 'text/plain',
      'Cache-Control': ok ? cacheFor(sitemapMaxAge(params.file, file.maxAge)) : 'no-store',
    },
  });
};
